macro_rules! deps {
    () => {
        TypeckRootCtxt!();
        CoroutineTypes!();
        Diverges!();
        DynamicCoerceMany!();
        DivergingFallbackBehavior!();
        EnclosingBreakables!();
        DivergingBlockBehavior!();
    };
}

macro_rules! FnCtxt {
    () => {
        deps!();
        # [doc = " The `FnCtxt` stores type-checking context needed to type-check bodies of"] # [doc = " functions, closures, and `const`s, including performing type inference"] # [doc = " with [`InferCtxt`]."] # [doc = ""] # [doc = " This is in contrast to `rustc_hir_analysis::collect::ItemCtxt`, which is"] # [doc = " used to type-check item *signatures* and thus does not perform type"] # [doc = " inference."] # [doc = ""] # [doc = " See `ItemCtxt`'s docs for more."] # [doc = ""] # [doc = " [`InferCtxt`]: infer::InferCtxt"] pub (crate) struct FnCtxt < 'a , 'tcx > { pub (super) body_id : LocalDefId , # [doc = " The parameter environment used for proving trait obligations"] # [doc = " in this function. This can change when we descend into"] # [doc = " closures (as they bring new things into scope), hence it is"] # [doc = " not part of `Inherited` (as of the time of this writing,"] # [doc = " closures do not yet change the environment, but they will"] # [doc = " eventually)."] pub (super) param_env : ty :: ParamEnv < 'tcx > , # [doc = " If `Some`, this stores coercion information for returned"] # [doc = " expressions. If `None`, this is in a context where return is"] # [doc = " inappropriate, such as a const expression."] # [doc = ""] # [doc = " This is a `RefCell<DynamicCoerceMany>`, which means that we"] # [doc = " can track all the return expressions and then use them to"] # [doc = " compute a useful coercion from the set, similar to a match"] # [doc = " expression or other branching context. You can use methods"] # [doc = " like `expected_ty` to access the declared return type (if"] # [doc = " any)."] pub (super) ret_coercion : Option < RefCell < DynamicCoerceMany < 'tcx > > > , # [doc = " First span of a return site that we find. Used in error messages."] pub (super) ret_coercion_span : Cell < Option < Span > > , pub (super) coroutine_types : Option < CoroutineTypes < 'tcx > > , # [doc = " Whether the last checked node generates a divergence (e.g.,"] # [doc = " `return` will set this to `Always`). In general, when entering"] # [doc = " an expression or other node in the tree, the initial value"] # [doc = " indicates whether prior parts of the containing expression may"] # [doc = " have diverged. It is then typically set to `Maybe` (and the"] # [doc = " old value remembered) for processing the subparts of the"] # [doc = " current expression. As each subpart is processed, they may set"] # [doc = " the flag to `Always`, etc. Finally, at the end, we take the"] # [doc = " result and \"union\" it with the original value, so that when we"] # [doc = " return the flag indicates if any subpart of the parent"] # [doc = " expression (up to and including this part) has diverged. So,"] # [doc = " if you read it after evaluating a subexpression `X`, the value"] # [doc = " you get indicates whether any subexpression that was"] # [doc = " evaluating up to and including `X` diverged."] # [doc = ""] # [doc = " We currently use this flag for the following purposes:"] # [doc = ""] # [doc = " - To warn about unreachable code: if, after processing a"] # [doc = "   sub-expression but before we have applied the effects of the"] # [doc = "   current node, we see that the flag is set to `Always`, we"] # [doc = "   can issue a warning. This corresponds to something like"] # [doc = "   `foo(return)`; we warn on the `foo()` expression. (We then"] # [doc = "   update the flag to `WarnedAlways` to suppress duplicate"] # [doc = "   reports.) Similarly, if we traverse to a fresh statement (or"] # [doc = "   tail expression) from an `Always` setting, we will issue a"] # [doc = "   warning. This corresponds to something like `{return;"] # [doc = "   foo();}` or `{return; 22}`, where we would warn on the"] # [doc = "   `foo()` or `22`."] # [doc = " - To assign the `!` type to block expressions with diverging"] # [doc = "   statements."] # [doc = ""] # [doc = " An expression represents dead code if, after checking it,"] # [doc = " the diverges flag is set to something other than `Maybe`."] pub (super) diverges : Cell < Diverges > , # [doc = " If one of the function arguments is a never pattern, this counts as diverging code. This"] # [doc = " affect typechecking of the function body."] pub (super) function_diverges_because_of_empty_arguments : Cell < Diverges > , # [doc = " Whether the currently checked node is the whole body of the function."] pub (super) is_whole_body : Cell < bool > , pub (super) enclosing_breakables : RefCell < EnclosingBreakables < 'tcx > > , pub (super) root_ctxt : & 'a TypeckRootCtxt < 'tcx > , pub (super) fallback_has_occurred : Cell < bool > , pub (super) diverging_fallback_behavior : DivergingFallbackBehavior , pub (super) diverging_block_behavior : DivergingBlockBehavior , # [doc = " Clauses that we lowered as part of the `impl_trait_in_bindings` feature."] # [doc = ""] # [doc = " These are stored here so we may collect them when canonicalizing user"] # [doc = " type ascriptions later."] pub (super) trait_ascriptions : RefCell < ItemLocalMap < Vec < ty :: Clause < 'tcx > > > > , # [doc = " Whether the current crate enables the `rustc_attrs` feature."] # [doc = " This allows to skip processing attributes in many places."] pub (super) has_rustc_attrs : bool , }
    };
}

FnCtxt!()